#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Bootstraps one copy of iac-aws, from a brand-new AWS account to CI deploying the org.
# Run from the repo root: bash scripts/bootstrap.sh
#
# The temporary admin key (IAM user iac-aws-bootstrap) lives only in this process's environment. It is never
# written to disk, and the last stage has you delete the user. Root never gets an access key:
# AWS does not let root assume roles, which every member-account deploy needs.
#
# Keep STATE_KEY_ALIAS and the bucket name in sync with src/state.ts.

TOTAL_STAGES=9

STACK="main"
STATE_KEY_ALIAS="alias/iac-aws-state"
BOOTSTRAP_USER="iac-aws-bootstrap"

# AWS CLI on Windows prints CRLF; strip it so captured values compare cleanly.
awsq() { aws "$@" | tr -d '\r'; }
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
# Strip all whitespace, including the \r a Windows console can append to typed or pasted input.
clean() { printf '%s' "$1" | tr -d '[:space:]'; }

# Git Bash on Windows: the library's explorer.exe exits non-zero even after opening the
# page, so open_url warns falsely. `start` opens the default browser and reports honestly.
if [[ "${OSTYPE:-}" == msys* || "${OSTYPE:-}" == cygwin* ]]; then
  open_url() {
    printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$1"
    cmd.exe //c start "" "$1" >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $1"
  }
fi

[[ -f Pulumi.yaml && -d policies/scp ]] || { printf 'Run this from the iac-aws repo root.\n' >&2; exit 1; }
[[ -f org.yaml ]] || { printf 'No org.yaml. Copy org.example.yaml to org.yaml, fill it in, then re-run.\n' >&2; exit 1; }

REGION=$(sed -n 's/^region:[[:space:]]*\([a-z0-9-]*\).*/\1/p' org.yaml)
SELF_REPO=$(sed -n 's/^selfRepo:[[:space:]]*\([^[:space:]#]*\).*/\1/p' org.yaml)

banner "iac-aws bootstrap"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check tools and org.yaml"
missing=()
for tool in node npm pulumi aws gh git; do command -v "$tool" >/dev/null 2>&1 || missing+=("$tool"); done
if (( ${#missing[@]} )); then
  warn "missing: ${missing[*]}. Install them and re-run."
  exit 1
fi
# selfRepo must equal the repo part of the subject GitHub puts in this repo's OIDC tokens:
# owner/repo, or owner@<id>/repo@<id> for repos created after 2026-07-15.
current_repo=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null | tr -d '\r' || true)
oidc_repo=""
if [[ -n "$current_repo" ]]; then
  oidc_repo=$(gh api "repos/$current_repo/actions/oidc/customization/sub" --jq '.sub_claim_prefix // ""' 2>/dev/null | tr -d '\r' || true)
  oidc_repo=${oidc_repo#repo:}
fi
if [[ -z "$oidc_repo" ]]; then
  warn "Couldn't read this repo's OIDC subject from GitHub; assuming '${current_repo:-unknown}'."
  oidc_repo=$current_repo
fi
if [[ "$SELF_REPO" != "$oidc_repo" ]]; then
  warn "selfRepo in org.yaml is '$SELF_REPO', but GitHub's tokens for this repo say '$oidc_repo'."
  warn "AWS would reject every CI run. They must match exactly."
  if confirm "Set selfRepo to '$oidc_repo' in org.yaml?"; then
    tmp=$(mktemp)
    sed "s|^selfRepo:.*|selfRepo: $oidc_repo|" org.yaml > "$tmp" && mv "$tmp" org.yaml
    SELF_REPO=$oidc_repo
    ok "updated selfRepo in org.yaml"
  else
    confirm "Continue anyway?" || exit 1
  fi
fi
say "Installing dependencies and validating org.yaml…"
npm ci --silent --no-audit --no-fund
if ! npm test --silent >/dev/null 2>&1; then
  warn "Tests failed. Run 'npm test' to see what is wrong with org.yaml."
  exit 1
fi
ok "org.yaml is valid · region $REGION · repo $SELF_REPO"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the management account"
if confirm "Already created the management account and turned on root MFA?"; then
  ok "skipping"
else
  say "Each organization needs its own, brand-new AWS account to be its management account."
  note "Use a fresh plus-address, e.g. you+org-<name>@gmail.com. Member accounts use the"
  note "accountEmail pattern from org.yaml."
  open_url "https://portal.aws.amazon.com/billing/signup"
  step "Sign up with that email. The Basic (free) support plan is enough."
  step "Once the account is active, sign in as the root user."
  pause "Press Enter once you're signed in as root."
  open_url "https://console.aws.amazon.com/iam/home#/security_credentials"
  step "Under 'Multi-factor authentication (MFA)', click 'Assign MFA device' and finish the setup."
  pause "Press Enter once MFA is on."
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Temporary admin user"
say "Pulumi needs credentials for the very first deploy. After that, CI uses OIDC and this user is deleted."
note "Not a root access key: AWS never lets root assume roles, and the deploy reaches every"
note "member account by assuming OrganizationAccountAccessRole."
open_url "https://console.aws.amazon.com/iam/home#/users/create"
step "As root: user name ${BOOTSTRAP_USER}, no console access → Next."
step "'Attach policies directly' → tick AdministratorAccess → Next → Create user."
step "Open ${BOOTSTRAP_USER} → 'Security credentials' tab → 'Create access key'."
step "Use case 'Command Line Interface (CLI)', tick the confirmation → Next → 'Create access key'."
step "Copy the Access key ID and the Secret access key. Keep the page open until both are pasted."
export AWS_REGION="$REGION" AWS_DEFAULT_REGION="$REGION"
unset AWS_PROFILE AWS_SESSION_TOKEN
while true; do
  ask AWS_ACCESS_KEY_ID "Access key ID:"
  ask_secret AWS_SECRET_ACCESS_KEY "Secret access key:"
  AWS_ACCESS_KEY_ID=$(clean "$AWS_ACCESS_KEY_ID")
  AWS_SECRET_ACCESS_KEY=$(clean "$AWS_SECRET_ACCESS_KEY")
  export AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY
  if [[ ! "$AWS_ACCESS_KEY_ID" =~ ^AKIA[A-Z0-9]{16}$ ]]; then
    warn "That doesn't look like an access key ID: expected AKIA plus 16 letters or digits (got ${#AWS_ACCESS_KEY_ID} characters)."
  elif (( ${#AWS_SECRET_ACCESS_KEY} != 40 )); then
    warn "The secret access key should be 40 characters; got ${#AWS_SECRET_ACCESS_KEY}."
  elif result=$(aws sts get-caller-identity --query '[Account,Arn]' --output text 2>&1); then
    identity=$(tr -d '\r' <<<"$result")
    [[ "$identity" != *:root ]] && break
    warn "That is a root access key. Root can't assume roles, so the deploy would fail."
    note "Create the ${BOOTSTRAP_USER} user's key instead, and delete the root key."
  else
    warn "AWS rejected the key:"
    note "$(tr -d '\r' <<<"$result")"
    note "A brand-new key can take a few seconds to start working."
  fi
  confirm "Try again?" || exit 1
done
ACCOUNT_ID=$(cut -f1 <<<"$identity")
ok "signed in to account $ACCOUNT_ID as $(cut -f2 <<<"$identity")"
if awsq organizations describe-organization >/dev/null 2>&1; then
  warn "This account already belongs to an organization. iac-aws expects a brand-new account,"
  warn "unless you are re-running this wizard after the first deploy."
  confirm "Continue?" || exit 1
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
STATE_BUCKET="iac-aws-state-${ACCOUNT_ID}"
stage "State backend"
say "Pulumi keeps its state in S3 and encrypts secrets with KMS, both in this account:"
note "  bucket   s3://${STATE_BUCKET}  (versioned, private, TLS only)"
note "  KMS key  ${STATE_KEY_ALIAS}  (automatic rotation)"
note "The stack never manages these itself, so it can never delete its own state."
if awsq kms describe-key --key-id "$STATE_KEY_ALIAS" >/dev/null 2>&1; then
  ok "KMS key $STATE_KEY_ALIAS already exists"
elif confirm "Create the KMS key?"; then
  key_id=$(awsq kms create-key --description "iac-aws Pulumi secrets" --query KeyMetadata.KeyId --output text)
  awsq kms create-alias --alias-name "$STATE_KEY_ALIAS" --target-key-id "$key_id"
  awsq kms enable-key-rotation --key-id "$key_id"
  ok "created KMS key $STATE_KEY_ALIAS"
else
  exit 1
fi
if awsq s3api head-bucket --bucket "$STATE_BUCKET" >/dev/null 2>&1; then
  ok "bucket $STATE_BUCKET already exists"
elif confirm "Create the state bucket?"; then
  if [[ "$REGION" == "us-east-1" ]]; then
    awsq s3api create-bucket --bucket "$STATE_BUCKET" >/dev/null
  else
    awsq s3api create-bucket --bucket "$STATE_BUCKET" \
      --create-bucket-configuration "LocationConstraint=$REGION" >/dev/null
  fi
  ok "created bucket $STATE_BUCKET"
else
  exit 1
fi
# Re-applied on every run so a half-finished earlier run converges.
tls_only_policy=$(printf '{"Version":"2012-10-17","Statement":[{"Sid":"TlsOnly","Effect":"Deny","Principal":"*","Action":"s3:*","Resource":["arn:aws:s3:::%s","arn:aws:s3:::%s/*"],"Condition":{"Bool":{"aws:SecureTransport":"false"}}}]}' "$STATE_BUCKET" "$STATE_BUCKET")
awsq s3api put-bucket-versioning --bucket "$STATE_BUCKET" --versioning-configuration Status=Enabled
awsq s3api put-public-access-block --bucket "$STATE_BUCKET" --public-access-block-configuration \
  BlockPublicAcls=true,IgnorePublicAcls=true,BlockPublicPolicy=true,RestrictPublicBuckets=true
awsq s3api put-bucket-policy --bucket "$STATE_BUCKET" --policy "$tls_only_policy"
ok "versioning, public access block and TLS-only policy in place"
PULUMI_BACKEND_URL="s3://${STATE_BUCKET}?region=${REGION}&awssdk=v2"
export PULUMI_BACKEND_URL
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Pulumi stack"
say "Creating stack '$STACK' in the S3 backend, with secrets encrypted by $STATE_KEY_ALIAS."
note "This shell uses PULUMI_BACKEND_URL; your global 'pulumi login' is left alone."
if pulumi stack select "$STACK" --non-interactive >/dev/null 2>&1; then
  ok "stack $STACK already exists"
else
  pulumi stack init "$STACK" --non-interactive \
    --secrets-provider "awskms://${STATE_KEY_ALIAS}?region=${REGION}"
  ok "created stack $STACK (Pulumi.$STACK.yaml holds its encrypted data key; it gets committed)"
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "First deploy"
say "Pulumi previews what it is about to create, then you confirm."
note "Each new account takes a few minutes. If one isn't ready in time, re-run this wizard;"
note "every stage skips what is already done."
identity_center_instance() {
  awsq sso-admin list-instances --query 'Instances[0].InstanceArn' --output text 2>/dev/null | grep -v '^None$' || true
}
WANTS_IDENTITY_CENTER=false
grep -q '^identityCenter:' org.yaml && WANTS_IDENTITY_CENTER=true
skip_admins=0
if $WANTS_IDENTITY_CENTER && [[ -z "$(identity_center_instance)" ]]; then
  note "Identity Center isn't enabled yet, so this deploy skips the admins. The next stage"
  note "enables it, and CI creates them in stage 8."
  skip_admins=1
fi
# Pulumi only prompts in a terminal it recognises, and Git Bash started from PowerShell is not one,
# so preview first and let the wizard ask.
IAC_AWS_MODE=deploy IAC_AWS_SKIP_IDENTITY_CENTER=$skip_admins pulumi preview --stack "$STACK" --non-interactive
confirm "Deploy these changes?" || exit 1
IAC_AWS_MODE=deploy IAC_AWS_SKIP_IDENTITY_CENTER=$skip_admins pulumi up --stack "$STACK" --yes --skip-preview --non-interactive
PLAN_ROLE_ARN=$(pulumi stack output planRoleArn --stack "$STACK" | tr -d '\r')
DEPLOY_ROLE_ARN=$(pulumi stack output deployRoleArn --stack "$STACK" | tr -d '\r')
ok "deployed · plan role $PLAN_ROLE_ARN"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "IAM Identity Center"
if ! $WANTS_IDENTITY_CENTER; then
  ok "no identityCenter in org.yaml, skipping"
elif [[ -n "$(identity_center_instance)" ]]; then
  ok "already enabled"
  note "If you haven't yet: Settings → Authentication → Standard authentication → Configure →"
  note "tick 'Send email OTP' → Save. Without it, admins created by iac-aws can't set a password."
else
  say "Admins sign in through IAM Identity Center. It has to be enabled once, by hand, in $REGION."
  open_url "https://console.aws.amazon.com/singlesignon/home?region=$REGION"
  step "As root, check the region selector says $REGION, then click 'Enable'."
  step "Choose the organization instance ('Enable with AWS Organizations') and confirm."
  step "Then Settings → Authentication tab → Standard authentication → Configure."
  step "Tick 'Send email OTP' → Save. This lets admins created by iac-aws set their own password."
  until [[ -n "$(identity_center_instance)" ]]; do
    pause "Press Enter once Identity Center is enabled."
    [[ -n "$(identity_center_instance)" ]] && break
    warn "No Identity Center instance in $REGION yet. Check the region, or wait a few seconds."
    confirm "Check again?" || exit 1
  done
  ok "Identity Center is enabled; CI will create the admins"
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Hand over to CI"
say "Setting the repo variables the preview and up workflows read."
set_var IAC_AWS_PLAN_ROLE_ARN "$PLAN_ROLE_ARN"
set_var IAC_AWS_DEPLOY_ROLE_ARN "$DEPLOY_ROLE_ARN"
set_var AWS_REGION "$REGION"
set_var PULUMI_BACKEND_URL "$PULUMI_BACKEND_URL"
[[ "$STACK" == "main" ]] || set_var PULUMI_STACK "$STACK"
say ""
latest_up_run() {
  gh run list --workflow up.yml --limit 1 --json databaseId --jq '.[0].databaseId // ""' 2>/dev/null | tr -d '\r' || true
}
# Wait for an up run newer than $1 and require it to pass: stage 8 deletes the only
# credentials that could fix a broken CI trust.
wait_for_new_up_run() {
  local before="$1" run_id=""
  say "Waiting for the 'up' workflow, to prove CI can deploy without ${BOOTSTRAP_USER}…"
  for _ in $(seq 1 24); do
    sleep 5
    run_id=$(latest_up_run)
    [[ -n "$run_id" && "$run_id" != "$before" ]] && break
    run_id=""
  done
  if [[ -n "$run_id" ]] && gh run watch "$run_id" --exit-status >/dev/null 2>&1; then
    ok "CI deployed successfully"
    if $WANTS_IDENTITY_CENTER; then
      portal=$(pulumi stack output accessPortalUrl --stack "$STACK" 2>/dev/null | tr -d '\r' || true)
      [[ -n "$portal" ]] && note "Admins: sign in at $portal with your email; a one-time code arrives by email."
    fi
  else
    warn "The up workflow did not succeed${run_id:+ (run $run_id)}. Check the Actions tab."
    warn "Fix it before deleting ${BOOTSTRAP_USER}; it is the only way in besides CI."
    confirm "Continue to the last stage anyway?" || exit 1
  fi
}
before_run=$(latest_up_run)
branch=$(git rev-parse --abbrev-ref HEAD)
say "org.yaml and Pulumi.$STACK.yaml need to be on main for CI to deploy."
if [[ -n "$(git status --porcelain -- org.yaml "Pulumi.$STACK.yaml")" ]]; then
  if confirm "Commit them and push to $branch?"; then
    git add org.yaml "Pulumi.$STACK.yaml"
    git commit -q -m "Bootstrap organization"
    git push -q
    ok "pushed"
    wait_for_new_up_run "$before_run"
  else
    SKIPPED+=("commit and push org.yaml and Pulumi.$STACK.yaml")
  fi
else
  ok "already committed"
  if confirm "Run the up workflow now to prove CI can deploy?"; then
    gh workflow run up.yml --ref "$branch" >/dev/null
    wait_for_new_up_run "$before_run"
  fi
fi
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Delete the temporary admin user"
say "CI deploys through OIDC now. The bootstrap user and its key must go."
open_url "https://console.aws.amazon.com/iam/home#/users"
step "As root: tick ${BOOTSTRAP_USER} → Delete → type the user name to confirm → Delete."
step "If you ever created a root access key, delete it too: account menu → Security credentials."
pause "Press Enter once the user is deleted."
if awsq sts get-caller-identity >/dev/null 2>&1; then
  warn "Key $AWS_ACCESS_KEY_ID still works. Delete ${BOOTSTRAP_USER} before you walk away."
  SKIPPED+=("delete IAM user ${BOOTSTRAP_USER} (key $AWS_ACCESS_KEY_ID)")
else
  ok "key $AWS_ACCESS_KEY_ID no longer works"
fi
unset AWS_ACCESS_KEY_ID AWS_SECRET_ACCESS_KEY
note "From here on, Pulumi runs only in CI: edit org.yaml in a PR, read the preview, merge to apply."

finish
